// Positions where Python forbids a walrus, slices, and other path shapes.
export const pythonTraceSemanticsPositionCases: readonly PythonTraceSemanticsCase[] = [
  {
    id: 'comprehension-iterable-paths',
    code: lines(
      'class Graph:',
      '    def __init__(self):',
      '        self.adj = {0: [1, 2], 1: [0]}',
      '    def doubled(self, u):',
      '        return [2 * v for v in self.adj[u]]',
      'def solve():',
      '    a = [[1, 2], [3, 4]]',
      '    def f():',
      '        a[0] = [7, 8]',
      '        return 0',
      '    first = [x for x in a[0][f():]]',
      '    rows = [[5, 6]]',
      '    second = [y for y in rows[0]]',
      '    return [first, second, Graph().doubled(0)]',
    ),
    expected: { value: [[1, 2], [5, 6], [2, 4]] },
  },
  {
    id: 'class-body-statements-and-comprehensions',
    code: lines(
      'from enum import Enum',
      'class Table:',
      '    grid = [[1, 2], [3, 4]]',
      '    grid[0][1] = 9',
      '    grid[1][0] += 1',
      '    picks = [row[0] for row in grid[0:2]]',
      '    def first(self, row=grid[1], *, col=grid[0][0]):',
      '        return [row[0], col]',
      'class Color(Enum):',
      '    lookup = {}',
      '    lookup["r"] = 1',
      '    RED = 1',
      'def solve():',
      '    return [Table.grid, Table.picks, Table().first(), sorted(Color.__members__), sorted(k for k in vars(Table) if not k.startswith("__"))]',
    ),
    expected: { value: [[[1, 9], [4, 4]], [1, 4], [4, 1], ['RED', 'lookup'], ['first', 'grid', 'picks']] },
  },
  {
    id: 'generator-lambda-and-default-reads',
    code: lines(
      'def solve():',
      '    dp = [[1, 2], [3, 4]]',
      '    pairs = [(2, [9, 1]), (1, [8, 0])]',
      '    total = sum(dp[i][j] for i in range(2) for j in range(2))',
      '    pairs.sort(key=lambda p: p[1][1])',
      '    def pick(row=dp[1]):',
      '        return row[0]',
      '    def gen():',
      '        for i in range(2):',
      '            yield dp[i][1 - i]',
      '    return [total, pairs, pick(), list(gen())]',
    ),
    expected: { value: [10, [[1, [8, 0]], [2, [9, 1]]], 3, [2, 3]] },
  },
  {
    id: 'slice-reads-writes-deletes',
    code: lines(
      'def solve():',
      '    a = [0, 1, 2, 3, 4, 5]',
      '    i = 1',
      '    head = a[i:3]',
      '    rev = a[::-1]',
      '    a[1:3] = [9]',
      '    a[0:1] += [7]',
      '    del a[-2:]',
      '    grid = [[1, 2, 3]]',
      '    grid[0][1:] = [5]',
      '    return [head, rev, a, grid]',
    ),
    expected: { value: [[1, 2], [5, 4, 3, 2, 1, 0], [0, 7, 9, 3], [[1, 5]]] },
  },
  {
    id: 'attribute-chains-and-deletes',
    code: lines(
      'class Inner:',
      '    def __init__(self):',
      '        self.count = 1',
      'class Outer:',
      '    def __init__(self):',
      '        self.inner = Inner()',
      '        self.seen = {"k": {1, 2}}',
      '        self.memo = {"k": {3: "x"}}',
      '        self.tmp = 5',
      '    def run(self):',
      '        self.inner.count += 2',
      '        del self.tmp',
      '        hit = 2 in self.seen["k"]',
      '        miss = 9 in self.seen["k"]',
      '        got = self.memo["k"].get(3)',
      '        return [self.inner.count, hasattr(self, "tmp"), hit, miss, got]',
      'def solve():',
      '    return Outer().run()',
    ),
    expected: { value: [3, false, true, false, 'x'] },
  },
  {
    id: 'private-names-in-comprehensions',
    code: lines(
      'class Store:',
      '    def __init__(self):',
      '        self.__rows = [[1, 2], [3, 4]]',
      '    def diag(self):',
      '        return [self.__rows[i][i] for i in range(2)]',
      '    def bump(self):',
      '        for i in range(2):',
      '            self.__rows[i][0] += 10',
      '        return self.__rows',
      'def solve():',
      '    s = Store()',
      '    return [s.diag(), s.bump()]',
    ),
    expected: { value: [[1, 4], [[11, 2], [13, 4]]] },
  },
  {
    // Recording an extend used to iterate the argument a second time.
    id: 'recording-runs-no-learner-code',
    code: lines(
      'calls = []',
      'class Source:',
      '    def __iter__(self):',
      '        calls.append("iter")',
      '        return iter([7, 8])',
      'def solve():',
      '    a = [3, 1]',
      '    a.extend(Source())',
      '    rows = [[5]]',
      '    rows[0].extend(Source())',
      '    return [a, rows, calls]',
    ),
    expected: { value: [[3, 1, 7, 8], [[5, 7, 8]], ['iter', 'iter']] },
  },
  {
    id: 'module-level-global-root',
    code: lines(
      'counts = [0, 0]',
      'memo = {}',
      'def solve():',
      '    for i in range(3):',
      '        counts[i % 2] += 1',
      '        memo[i] = counts[i % 2]',
      '    return [counts, memo]',
    ),
    expected: { value: [[2, 1], { 0: 1, 1: 1, 2: 2 }] },
  },
  // A learner call adds one frame, traced or not, so a recursion that fits
  // under the limit untraced fits traced (functions and methods).
  {
    id: 'recursion-near-the-limit',
    code: lines(
      'import sys',
      'def depth(n):',
      '    return 0 if n == 0 else depth(n - 1) + 1',
      'class Walker:',
      '    def down(self, n, *, step=1):',
      '        return 0 if n == 0 else self.down(n - step, step=step) + 1',
      'def solve():',
      '    here = 0',
      '    frame = sys._getframe()',
      '    while frame is not None:',
      '        here += 1',
      '        frame = frame.f_back',
      '    target = sys.getrecursionlimit() - here - 50',
      '    return [depth(target) == target, Walker().down(target) == target]',
    ),
    expected: { value: [true, true] },
  },
  // Patterns are not expressions: value, class and mapping patterns stay as
  // written; guards and bodies are instrumented.
  {
    id: 'match-value-and-class-patterns',
    code: lines(
      'from enum import Enum',
      'class Status(Enum):',
      '    OK = 1',
      '    BAD = 2',
      'class Point:',
      '    __match_args__ = ("x", "y")',
      '    def __init__(self, x, y):',
      '        self.x = x',
      '        self.y = y',
      'class Limits:',
      '    HIGH = 2',
      'def solve():',
      '    out = []',
      '    grid = [[0, 1], [2, 3]]',
      '    for item in [Status.OK, Status.BAD, Point(1, 0), {"k": [1, 2]}]:',
      '        match item:',
      '            case Status.OK:',
      '                out.append("ok")',
      '            case Status.BAD if grid[1][0] >= Limits.HIGH:',
      '                out.append("bad")',
      '            case Point(x, y) if grid[x][y] == 2:',
      '                grid[x][y] += 1',
      '                out.append(grid[x])',
      '            case {"k": [a, b]}:',
      '                out.append(a + b)',
      '    return out',
    ),
    expected: { value: ['ok', 'bad', [3, 3], 3] },
  },
  // Async iteration stays async (driven without an event loop).
  {
    id: 'async-comprehensions-and-async-for',
    code: lines(
      'async def stream(n):',
      '    for i in range(n):',
      '        yield i',
      'async def collect(n):',
      '    gen = stream(n)',
      '    items = [x async for x in gen]',
      '    rows = [stream(n)]',
      '    doubled = {x: x * 2 async for x in rows[0]}',
      '    total = 0',
      '    async for x in stream(n):',
      '        total += x',
      '    pairs = [(i, x) async for i, x in pairs_of(n)]',
      '    return [items, doubled, total, pairs]',
      'async def pairs_of(n):',
      '    async for x in stream(n):',
      '        yield (x, x * x)',
      'def solve():',
      '    coroutine = collect(3)',
      '    try:',
      '        coroutine.send(None)',
      '    except StopIteration as done:',
      '        return done.value',
    ),
    expected: { value: [[0, 1, 2], { 0: 0, 1: 2, 2: 4 }, 3, [[0, 0], [1, 1], [2, 4]]] },
  },
  // A class body cannot capture an index with a walrus; its loops still run.
  {
    id: 'class-body-loop-over-indexed-iterable',
    code: lines(
      'class Table:',
      '    rows = [[1, 2], [3]]',
      '    k = 1',
      '    flat = []',
      '    for x in rows[0]:',
      '        flat.append(x * 10)',
      '    for x in rows[k]:',
      '        flat.append(x)',
      '    for x in rows[0][1:]:',
      '        flat.append(-x)',
      '    del x',
      'def solve():',
      '    return [Table.flat, hasattr(Table, "x")]',
    ),
    expected: { value: [[10, 20, 3, -2], false] },
  },
  // Recording an index never runs the index's own dunders (Python's native
  // indexing calls only Idx.__index__, once per access).
  {
    id: 'index-dunders-run-only-natively',
    code: lines(
      'class K(int):',
      '    calls = []',
      '    def __int__(self):',
      '        K.calls.append("int")',
      '        return 99',
      '    def __str__(self):',
      '        K.calls.append("str")',
      '        return "K"',
      '    def __repr__(self):',
      '        K.calls.append("repr")',
      '        return "K"',
      '    def __format__(self, spec):',
      '        K.calls.append("format")',
      '        return "K"',
      'class Idx:',
      '    def __init__(self, v):',
      '        self.v = v',
      '    def __index__(self):',
      '        K.calls.append("index")',
      '        return self.v',
      'def solve():',
      '    a = [10, 20, 30, 40]',
      '    grid = [[1, 2], [3, 4]]',
      '    out = [a[K(1)], a[K(0):K(2)], grid[K(1)][K(0)]]',
      '    a[K(2)] = 7',
      '    grid[K(0)][K(1)] += 5',
      '    out.append(a[Idx(3)])',
      '    out.append(a[Idx(1):])',
      '    grid[0][Idx(0):Idx(1)] = [8]',
      '    del a[K(0)]',
      '    return [out, a, grid, K.calls]',
    ),
    expected: {
      value: [[20, [10, 20], 3, 40, [20, 7, 40]], [20, 7, 40], [[8, 7], [3, 4]], ['index', 'index', 'index', 'index']],
    },
  },
  // An index that deletes or rebinds the root (nonlocal) after Python has
  // evaluated it: stores, deletes and tuple-target stores record the object
  // Python wrote to.
  {
    id: 'index-unbinds-or-rebinds-the-root',
    code: lines(
      'def solve():',
      '    a = [0, 0, 0]',
      '    keep = a',
      '    grid = [[0, 0]]',
      '    def drop(k):',
      '        nonlocal a',
      '        del a',
      '        return k',
      '    def rebind(k):',
      '        nonlocal a',
      '        a = [9, 9, 9]',
      '        return k',
      '    a[drop(1)] = 5',
      '    a = keep',
      '    del a[drop(0)]',
      '    a = keep',
      '    a[rebind(0)], b = 7, 1',
      '    rows = grid',
      '    def drop_rows(k):',
      '        nonlocal rows',
      '        del rows',
      '        return k',
      '    rows[0][drop_rows(1)] = 3',
      '    return [keep, a, b, grid]',
    ),
    expected: { value: [[7, 0], [9, 9, 9], 1, [[0, 3]]] },
  },
  // Recording extend reads the appended cells back; it never iterates the
  // argument again (a builtin zip over a learner iterator).
  {
    id: 'extend-records-without-reiterating',
    code: lines(
      'from collections import deque',
      'def solve():',
      '    it = iter([1, 2, 3, 4, 5, 6])',
      '    a = []',
      '    a.extend(zip(it, [0]))',
      '    grid = [[], []]',
      '    grid[1].extend(map(lambda x: x * 10, it))',
      '    q = deque([0])',
      '    rest = iter([7, 8, 9])',
      '    q.extend(zip(rest, "a"))',
      '    return [a, grid, list(q), list(rest)]',
    ),
    expected: { value: [[[1, 0]], [[], [30, 40, 50, 60]], [0, [7, 'a']], [9]] },
  },
  // Names of the tracing form (temps, helpers) would collide with the
  // instrumentation: such a program runs untraced, never with a changed
  // result or a learner SyntaxError.
  {
    id: 'reserved-helper-name-runs-untraced',
    code: lines(
      'def _tracecode_read_index(*args):',
      '    return "learner helper"',
      'def solve():',
      '    a = [[1, 2], [3, 4]]',
      '    return [a[1][1], _tracecode_read_index()]',
    ),
    expected: { value: [4, 'learner helper'] },
    traceUnavailable: true,
  },
  {
    id: 'reserved-temp-name-runs-untraced',
    code: lines(
      'def solve():',
      '    a = [[1, 2], [3, 4]]',
      '    return [a[__tracecode_index_0][0] for __tracecode_index_0 in range(2)]',
    ),
    expected: { value: [1, 3] },
    traceUnavailable: true,
  },
  // Recording never formats an exception with learner code: the raise site
  // runs before the program's except clause, and a failure's message is
  // formatted only after the program finished, with a failing __str__
  // keeping the original failure.
  {
    id: 'exception-str-runs-only-when-the-program-asks',
    code: lines(
      'class Loud(Exception):',
      '    seen = []',
      '    def __str__(self):',
      '        Loud.seen.append(len(Loud.seen))',
      '        return "loud"',
      'class Arg:',
      '    def __repr__(self):',
      '        Loud.seen.append("arg-repr")',
      '        return "Arg"',
      'def solve():',
      '    try:',
      '        raise Loud("x")',
      '    except Loud as error:',
      '        message = str(error)',
      '    try:',
      '        raise KeyError(Arg())',
      '    except KeyError:',
      '        pass',
      '    try:',
      '        raise ValueError("plain")',
      '    except ValueError as error:',
      '        plain = str(error)',
      '    return [message, plain, Loud.seen]',
    ),
    expected: { value: ['loud', 'plain', [0]] },
  },
  {
    id: 'uncaught-exception-with-failing-str',
    code: lines(
      'class Broken(Exception):',
      '    def __str__(self):',
      '        raise RuntimeError("no text")',
      'def solve():',
      '    raise Broken()',
    ),
    expected: { error: ['Broken', 'Execution failed'] },
  },
  // Snapshots run no learner code: learner dunders (repr, str, iter, len,
  // lt, eq, hash, getattribute of internal names, int/str subclass
  // overrides) log every call, and tracing adds none to the log.
  {
    id: 'snapshot-runs-no-learner-dunders',
    code: lines(
      'log = []',
      'class Loud:',
      '    def __init__(self, n):',
      '        self.n = n',
      '    def __repr__(self):',
      '        log.append("repr")',
      '        return "L"',
      '    def __str__(self):',
      '        log.append("str")',
      '        return "L"',
      '    def __lt__(self, other):',
      '        log.append("lt")',
      '        return False',
      '    def __eq__(self, other):',
      '        log.append("eq")',
      '        return self is other',
      '    def __hash__(self):',
      '        log.append("hash")',
      '        return self.n',
      '    def __len__(self):',
      '        log.append("len")',
      '        return 1',
      '    def __iter__(self):',
      '        log.append("iter")',
      '        return iter([self.n])',
      '    def __getattribute__(self, name):',
      '        if name in ("__dict__", "__class__", "val", "left", "right", "next", "__name__"):',
      '            log.append("get " + name)',
      '        return object.__getattribute__(self, name)',
      'class Bag(list):',
      '    def __iter__(self):',
      '        log.append("bag-iter")',
      '        return list.__iter__(self)',
      '    def __len__(self):',
      '        log.append("bag-len")',
      '        return list.__len__(self)',
      '    def __getitem__(self, index):',
      '        log.append("bag-getitem")',
      '        return list.__getitem__(self, index)',
      'class Table(dict):',
      '    def items(self):',
      '        log.append("table-items")',
      '        return dict.items(self)',
      '    def __iter__(self):',
      '        log.append("table-iter")',
      '        return dict.__iter__(self)',
      '    def __len__(self):',
      '        log.append("table-len")',
      '        return dict.__len__(self)',
      'class Count(int):',
      '    def __int__(self):',
      '        log.append("count-int")',
      '        return 0',
      '    def __repr__(self):',
      '        log.append("count-repr")',
      '        return "C"',
      '    def __ne__(self, other):',
      '        log.append("count-ne")',
      '        return True',
      'class Name(str):',
      '    def __str__(self):',
      '        log.append("name-str")',
      '        return "?"',
      'class Slotted:',
      '    __slots__ = ("x",)',
      '    def __init__(self):',
      '        self.x = 1',
      '    def __repr__(self):',
      '        log.append("slot-repr")',
      '        return "S"',
      'def solve():',
      '    a = Loud(1)',
      '    b = Loud(2)',
      '    items = Bag([a, 3])',
      '    table = Table({a: 1, Name("k"): 2, (1, "x"): 3})',
      '    group = {a, b}',
      '    frozen = frozenset([b])',
      '    view = table.keys()',
      '    error = ValueError(a)',
      '    window = slice(a, None)',
      '    counted = Count(5)',
      '    label = Name("z")',
      '    slotted = Slotted()',
      '    nested = [table, items]',
      '    first = nested[0]',
      '    total = counted + 1',
      '    return [list(log), total, len(group), first is table]',
    ),
    expected: { value: [['hash', 'hash', 'hash', 'hash'], 6, 2, true] },
  },
  // Raising learner dunders neither change the program nor reach it from
  // recording (a read whose value holds a key with a raising __str__).
  {
    id: 'snapshot-survives-raising-dunders',
    code: lines(
      'class Boom:',
      '    def __repr__(self):',
      '        raise RuntimeError("repr")',
      '    def __str__(self):',
      '        raise RuntimeError("str")',
      '    def __len__(self):',
      '        raise RuntimeError("len")',
      '    def __iter__(self):',
      '        raise RuntimeError("iter")',
      '    def __lt__(self, other):',
      '        raise RuntimeError("lt")',
      '    @property',
      '    def val(self):',
      '        raise RuntimeError("val")',
      'class BoomKey(str):',
      '    def __str__(self):',
      '        raise RuntimeError("key")',
      'def solve():',
      '    boom = Boom()',
      '    holder = {"b": boom, BoomKey("k"): [boom]}',
      '    group = {boom}',
      '    frozen = frozenset([boom])',
      '    error = KeyError(boom)',
      '    rows = [{BoomKey("k"): 1}, boom]',
      '    inner = rows[0]',
      '    rows[1] = {BoomKey("j"): boom}',
      '    return ["ok", len(inner), len(holder)]',
    ),
    expected: { value: ['ok', 1, 2] },
  },
  // A learner method named like a recorded builtin method (get, append) is
  // called natively, so its recursion reaches the untraced depth.
  {
    id: 'recursive-get-and-append-methods',
    code: lines(
      'import sys',
      'class Memo:',
      '    def get(self, n, default=None):',
      '        return 0 if n == 0 else self.get(n - 1) + 1',
      'class Chain:',
      '    def __init__(self):',
      '        self.links = [self]',
      '    def append(self, n):',
      '        return 0 if n == 0 else self.links[0].append(n - 1) + 1',
      'def solve():',
      '    here = 0',
      '    frame = sys._getframe()',
      '    while frame is not None:',
      '        here += 1',
      '        frame = frame.f_back',
      '    target = sys.getrecursionlimit() - here - 50',
      '    memo = Memo()',
      '    chain = Chain()',
      '    seen = {"a": 1}',
      '    order = []',
      '    order.append(seen.get("a"))',
      '    order.append(seen.get("z", 5))',
      '    return [memo.get(target) == target, chain.append(target) == target, order]',
    ),
    expected: { value: [true, true, [1, 5]] },
  },
];
